# 1. Delete all caches in drivetrack and tigeriq-ai-lab
foreach ($r in @("drivetrack","tigeriq-ai-lab")) {
  $caches = gh api --paginate "repos/newsdayads/$r/actions/caches?per_page=100" --jq '.actions_caches[].id'
  $count = 0
  foreach ($id in $caches) {
    gh api -X DELETE "repos/newsdayads/$r/actions/caches/$id" | Out-Null
    $count++
  }
  Write-Host "$r : deleted $count caches"
}

# 2. Delete artifacts older than 2026-11-16 in drivetrack
$dtDeleted = 0
$page = 1
while ($true) {
  $resp = gh api "repos/newsdayads/drivetrack/actions/artifacts?per_page=100&page=$page" | ConvertFrom-Json
  if (-not $resp.artifacts -or $resp.artifacts.Count -eq 0) { break }
  $old = $resp.artifacts | Where-Object { $_.created_at -lt "2026-11-16T00:00:00Z" }
  if ($old.Count -eq 0) { $page++; continue }
  foreach ($a in $old) {
    gh api -X DELETE "repos/newsdayads/drivetrack/actions/artifacts/$($a.id)" | Out-Null
    $dtDeleted++
  }
  # Since items are deleted, re-fetch same page if many were deleted, else advance
  if ($old.Count -lt 50) { $page++ }
}
Write-Host "drivetrack: deleted $dtDeleted artifacts older than 2026-11-16"

